// Tempo 120 bpm
setCps(120/60/4)

// Basic mixer
const BASS_VOL=slider(1,0,1)
const HIHATS_VOL=slider(0.441,0,1)
const PADS_VOL=slider(0.624,0,1)

// Other modifiers
const BASS_ENERGY=slider(1.048,0,8)


// 4 on the floor
$kick: s("[sbd]*4").dist("3:.3").gain(1)._scope()

// Sidechain kick to orbit 2,3,4
.duck("2:3:4").duckattack(.2).duckdepth(.8)


// Random 303 bassline - not super random really, occasionally +1 octave
$bass: n(irand(2).almostNever(x=>x.add(7)).sub(7).seg(16)).scale("c:phrygian")._pianoroll()
// Make it repeatable
.rib(10,4)
// Heavy distortion
.dist("2:0.3")
// Nice tb303 with adjustable energy
.s("sawtooth").lpf(200).lpenv(BASS_ENERGY).lpq(12).gain(BASS_VOL)
// Make it pump with the duck
.orbit(2)

// Upbeats only
$hihats: s("[~ hh]*4").delay(0.1).gain(HIHATS_VOL)._scope()

// Subpad to keep it interesting, detuned, every 2 bars 
$subpad: s("supersaw").detune(1).rel(5).beat(2,32).slow(2).orbit(2)
.fm(slider(2,0,5)).fmh(slider(2.04,0,5)).room(1).roomsize(6).gain(PADS_VOL)


$riser: s("pulse").orbit(4).seg(16).dec(.1).fm(time).fmh(time)

setCpm(132/4)


// Bass drum - Kick
// It will duck the rest of the instruments to avoid interferences
// (duck + orbits down below)
$: s("bd!4").dist(slider(2.728,1,4)).duck("2:3:4").duckdepth(.1)
  .gain(slider(0.223))._scope()
// Basic drums - slider hi-hats, house downtempo hi-hat, claps
$: s("hh!16").gain(slider(0.162))
$: s("~ ~ hh ~").fast(4).delay(.2).gain(slider(0.314))
$: s("~ sd ~ sd").gain(slider(0.358)) 

// Lead
// Two oscilators, combining  wave table + sawtooth
// With longer decays (dec) we control the length of the notes
// The shorter, the pluckier
// We add diode distorsion
// Envelope controls the energy to give it an acid-techno vibe
// Trancegate provides a density in the pattern
$: n(irand(2).almostNever(x=>x.add(7)).sub(7).seg(16))  
  .ribbon(2,16)
  .scale("c:phrygian")
  .s("[wt_digital:1,sawtooth]!16")
  .wt(slider(0.823))
  .unison(2)
  .dec(slider(0.4483,.1,1))
  //.diode("3:.4")  
  .trancegate(slider(8.92,1,16),3,16)
  .acidenv(slider(0.729,0,1))
  .gain(slider(0.64))
  .o(2)._scope()

// Bass
